inputs = ['kjkchz', 'jufgj', 'yzbfez', 'xkgd', 'dyvf']
outputs = ['kyekchj', 'yeufgye', 'vaxjbfej', 'xkgd', 'dvaxvf']

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first difference and determine what needs changing
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return ("", s_out[len(s_in):], len(s_in))
        else:
            return (s_in[len(s_out):], "", len(s_out))

    # Look for patterns around this position
    # Check if we're inserting or replacing
    if len(s_in) < len(s_out):
        # Insertion case
        # Look for what was inserted
        inserted = s_out[pos:pos + (len(s_out) - len(s_in))]
        return ("", inserted, pos)
    elif len(s_in) > len(s_out):
        # Deletion case  
        deleted = s_in[pos:pos + (len(s_in) - len(s_out))]
        return (deleted, "", pos)
    else:
        # Same length - replacement
        return (s_in[pos], s_out[pos], pos)

